(()=>{const nav=[['index.html','Accueil','Home','home'],['services.html','Services','Services','services'],['projets.html','Projets','Projects','projets'],['outils.html','Outils','Tools','outils'],['contact.html','Contact','Contact','contact']];const header=document.getElementById('site-header'),footer=document.getElementById('site-footer');header.innerHTML='<header><div class="wrap"><a class="brand" href="index.html">ZB / DIGITAL STUDIO</a><nav aria-label="Navigation">'+nav.map(([u,fr,en,id])=>'<a href="'+u+'" data-fr="'+fr+'" data-en="'+en+'"'+(document.body.dataset.page===id?' aria-current="page"':'')+'>'+fr+'</a>').join('')+'<button class="lang" id="language" type="button">EN</button></nav></div></header>';footer.innerHTML='<footer><div class="wrap"><span>© Zakaria Benlacheheb · Digital Studio</span><a href="plan-du-site.html" data-fr="Plan du site" data-en="Site map">Plan du site</a></div></footer>';let lang='fr';try{lang=localStorage.getItem('zb-site-lang')||'fr'}catch(e){}function set(l){lang=l;document.documentElement.lang=l;document.querySelectorAll('[data-fr][data-en]').forEach(el=>el.textContent=el.dataset[l]);document.getElementById('language').textContent=l==='fr'?'EN':'FR';try{localStorage.setItem('zb-site-lang',l)}catch(e){}}document.getElementById('language').addEventListener('click',()=>set(lang==='fr'?'en':'fr'));set(lang)})();
